  vxKey(woodMat,'table.rails','Rails (wood)');vxKey(woodDarkMat,'table.dark-wood','Dark wood');vxKey(leatherMat,'table.leather','Leather');
  vxKey(pocketMat,'table.pocket-holes','Pocket holes');vxKey(slateMat,'table.slate','Slate');vxKey(metalMat,'table.metal','Dark metal (lamp, chair legs)');
  // The baize photo becomes a neutral weave (+ matching relief) so the cloth
