  const BALL_COLORS={cue:'#f3f0e4',red:'#a8121a',yellow:'#f0bd06',green:'#0b7038',brown:'#6a3618',blue:'#1340a4',pink:'#ee8e9f',black:'#09090b'};
  const ballMats={};
  // Phenolic resin: faint marbling and fine flecks in every ball (as in the
