    railShape.holes.push(pathFrom(notchedOutline(IN_X,IN_Z,railCircles,true)));
    const railGeo=new T.ExtrudeGeometry(railShape,{depth:RAIL_T-.012,bevelEnabled:true,bevelThickness:.006,bevelSize:.006,bevelSegments:4,curveSegments:32});
    railGeo.rotateX(-PI/2);railGeo.translate(0,RAIL_TOP-RAIL_T+.006,0);
