    const w=.0045,y=CLOTH_Y+.0004;
    const baulk=new T.Mesh(new T.PlaneGeometry(w,2*HZ).rotateX(-PI/2),chalkMat);baulk.position.set(BAULK_X,y,0);baulk.receiveShadow=true;scene.add(baulk);
