    const sign=new T.Mesh(new T.PlaneGeometry(b.gap*.9,.42),vmat("Players' sign",new T.MeshBasicMaterial({map:stageTexture(512,80,(g,w,h)=>{g.fillStyle='#08080b';g.fillRect(0,0,w,h);
      velvetEmblem(g,52,40,28,'#e3243a');g.fillStyle='#f2f2f2';g.font='800 36px Arial, sans-serif';g.textBaseline='middle';g.fillText('PLAYERS',96,42);}),toneMapped:false})));
    sign.position.set(0,FLOOR_Y+tH-.62,-tIn+.06);grp.add(sign);
    // stairways: a lit nosing on every step of every aisle
    const steps=[],lights=[],m4=new T.Matrix4(),q=new T.Quaternion(),Y=new T.Vector3(0,1,0),one=new T.Vector3(1,1,1);
    for(let r=1;r<b.rows;r++){const {R,y}=bowlRow(b,r);
      for(let k=0;k<b.sections;k++){const a=PI+(k/b.sections)*TAU;if(bowlGapHalf(b,r)&&Math.abs(Math.atan2(Math.sin(a-PI),Math.cos(a-PI)))<bowlGapHalf(b,r)+.02)continue;
        q.setFromAxisAngle(Y,a);steps.push(m4.compose(new T.Vector3(Math.sin(a)*(R-b.rowD/4+.12),y-b.rowH/2,Math.cos(a)*(R-b.rowD/4+.12)),q,one).clone());
        lights.push(m4.compose(new T.Vector3(Math.sin(a)*(R-b.rowD/2+.14),y+.012,Math.cos(a)*(R-b.rowD/2+.14)),q,one).clone());}}
    const stepI=new T.InstancedMesh(new T.BoxGeometry(b.aisle,b.rowH/2,b.rowD/2),nose,steps.length);steps.forEach((mm,i)=>stepI.setMatrixAt(i,mm));stepI.computeBoundingSphere();grp.add(stepI);
    const ledI=new T.InstancedMesh(new T.BoxGeometry(b.aisle*.8,.012,.03),vmat('Aisle lights',new T.MeshBasicMaterial({color:new T.Color('#9fb7ff').multiplyScalar(1.3),toneMapped:false})),lights.length);
    lights.forEach((mm,i)=>ledI.setMatrixAt(i,mm));ledI.computeBoundingSphere();grp.add(ledI);
