    front.position.y=FLOOR_Y+.47;grp.add(front);
    const fl=new T.Mesh(new T.TorusGeometry(b.r0-.72,.01,6,240,TAU-2*ga).rotateX(PI/2),red);fl.rotation.y=PI/2-ga;fl.position.y=FLOOR_Y+.93;grp.add(fl);
    // back wall, a lit fascia of boards round the top, and the dark roof with its rig of lamps
    const back=new T.Mesh(new T.CylinderGeometry(Rb,Rb,H-FLOOR_Y+.5,200,1,true),vmat('Back wall',new T.MeshStandardMaterial({color:'#08090b',roughness:.9,side:T.BackSide})));
    back.position.y=(H+FLOOR_Y)/2;grp.add(back);
    const fasciaTex=stageTexture(2048,128,(g,w,h)=>{g.fillStyle='#09090c';g.fillRect(0,0,w,h);
      for(let x=0;x<w;x+=512){velvetEmblem(g,x+62,64,40,'#e3243a');g.fillStyle='#f2f2f2';g.font=(x%1024?'700 34px':'800 46px')+' Arial, sans-serif';g.textBaseline='middle';g.fillText(x%1024?'WORLD CHAMPIONSHIP':'VELVET',x+118,66,380);}});
    fasciaTex.wrapS=T.RepeatWrapping;fasciaTex.repeat.set(-12,1);
    const fascia=new T.Mesh(new T.CylinderGeometry(Rb-.05,Rb-.05,1.0,200,1,true),vmat('Fascia boards',new T.MeshBasicMaterial({map:fasciaTex,side:T.BackSide,toneMapped:false,color:new T.Color(.7,.7,.7)})));
