      const back=new T.Mesh(new T.PlaneGeometry(BL,ceilY-FLOOR_Y-b.y),redWall);back.position.set(bx,(ceilY+FLOOR_Y+b.y)/2,sz*(b.z1-.02));back.rotation.y=sz<0?0:PI;grp.add(back);
