    const lampM=vmat('Boxes (ceiling lights)',new T.MeshBasicMaterial({color:new T.Color(1,.92,.8).multiplyScalar(1.6),toneMapped:false}));
    const downI=new T.InstancedMesh(new T.CircleGeometry(.09,12).rotateX(PI/2),lampM,down.length);
