        let k=L[Math.floor(Math.random()*L.length)];if(L.length>1&&k===c.lastHab)k=L[(L.indexOf(k)+1)%L.length];c.habNext=null;
        if(k){c.lastHab=k;const a=c.p.play(k,{weight:0});a.reset();a.play();c.hab=a;c.habAmt=0;
          c.habEnd=time+Math.min(a.getClip?a.getClip().duration:4,rand(3.5,7.5));}else c.habAt=time+20;
