    const rl=$('remaining-line');if(rl){const behind=state.scores[0]<state.scores[1]?0:state.scores[1]<state.scores[0]?1:-1;
      rl.hidden=state.mode==='practice';rl.innerHTML='REMAINING <b>'+pointsRemaining()+'</b>'+(behind>=0&&snookersNeeded(behind)?' <em>· '+playerName(behind)+' NEED'+(state.mode==='bot'&&behind===1?'S':'')+' SNOOKERS</em>':'');}
    const fs=$('frames-score');if(fs){const m=state.match;fs.textContent=state.mode==='practice'||m.bestOf===1?'VS':m.frames[0]+' · '+m.frames[1];fs.title=m.bestOf>1?'Frames · best of '+m.bestOf:'';}
    $('nomination-label').innerHTML=state.phase==='color'?'AUTO SELECT FROM AIM <span>· CLICK OVERRIDES</span>':state.phase==='red'?'POT A RED <span>· COLOURS NEXT</span>':'FINAL COLOURS <span>· IN ORDER</span>';
    $('ball-picker').hidden=true;
    document.querySelectorAll('.ball-option').forEach(btn=>btn.classList.toggle('selected',btn.dataset.color===state.nominated));
    const busy=state.inShot||state.finished||!state.started||(state.mode==='bot'&&!humanTurn());
    $('shoot-button').disabled=busy;
    $('shoot-hint').textContent=state.decision?'WAITING FOR A DECISION':state.finished?'FRAME ENDED':state.inShot?'BALLS IN MOTION':!humanTurn()?opponentShort()+' IS THINKING':state.ballInHand?'DRAG WHITE IN THE D':state.phase==='color'&&!state.nominated?'AIM AT A COLOUR · AUTO SELECT':'READY TO PLAY';
    $('shot-history').innerHTML=state.history.length?state.history.slice(0,4).map(h=>'<div class="history-row '+(h.foul?'foul':'')+'"><span class="history-bullet">'+(h.foul?'!':'›')+'</span><span>'+escapeHTML(h.text)+'</span></div>').join(''):'<div class="history-empty">Your first break awaits.</div>';
