  // ---- BOT PACE: watch the opponent think and walk up, or skip to its shot.
  let botFast=false;try{botFast=localStorage.getItem('velvet.botPace')==='skip';}catch(e){}
  const botSkipping=()=>botFast||!!ai.skipOnce;
  function paintBotPace(){const b=$('bot-pace-toggle');if(!b)return;b.textContent='BOT TURN · '+(botFast?'SKIP':'WATCH');b.classList.toggle('active',botFast);b.setAttribute('aria-pressed',String(botFast));}
