        if(!plan){ai.retryAt=performance.now()+1500;message(opponentShort()+' HAS NO CLEAR SHOT','THINKING AGAIN');return;}
        // a human takes longer over a hard shot or a safety, now and then much longer
        const hard=plan.kind==='pot'?1-clamp(plan.p??.6,0,1):plan.kind==='break'?.3:.85,mull=(.6+1.6*hard)*(Math.random()<.1?2.2:1);
